/**
 * Bridge, the part with no klinecharts at runtime (./indicator.ts binds it to
 * klinecharts' registry): turn a SuperScript (or any registered-language) script into a native
 * KLineChart indicator, so a script written by a user — or generated by AI — is
 * rendered on the SUPer-Chart canvas exactly like a built-in indicator.
 *
 * Usage:
 *   registerScriptIndicator({ name: 'SMA_CROSS', source });
 *   chart.createIndicator('SMA_CROSS', false, { id: 'candle_pane' });
 *   // later, in place (same pane, same height):
 *   updateScriptIndicator(chart, { name: 'SMA_CROSS', source: newSource });
 *
 * What the template carries, and why:
 *   - Every line figure gets a COMPLETE line style (style, smooth, size,
 *     dashedValue, color), indexed among line figures only: klinecharts 9.8
 *     does not merge indicator line styles with its defaults and reads
 *     `dashedValue[0]` while merging segments, so a partial style threw on
 *     every redraw and blanked the pane's other indicators and grid.
 *   - Histogram and circle colours come from each figure's `styles` callback
 *     (klinecharts indexes bar/circle styles separately from lines); a
 *     histogram grows from `histbase` (0), coloured by sign when the script
 *     gives no colour.
 *   - Only finite numbers reach klinecharts: NaN or ±Infinity in one bar used
 *     to blank the pane's axis (and the candles, on the price pane).
 *   - Legend titles end in ": ", and the value uses the price precision when
 *     the script plots on the price scale (`// @overlay` or `series:'price'`),
 *     otherwise 2 decimals. An update sets its instances' precision the way
 *     klinecharts' own series sync does, so later symbol changes still apply.
 *   - `input()` values are the indicator's calcParams, so overrideIndicator /
 *     the settings can change them.
 *
 * Maintained by ZzyzxLabs. Part of SUPer-Chart (Apache-2.0).
 */
import type { Chart, IndicatorFigure, IndicatorStyle, IndicatorTemplate, KLineData } from "klinecharts";
import { getLanguage, isSuperScriptError, type Bar, type Diagnostic, type ScriptInput, type ScriptParams } from "./index";
import { ACCENT } from "../theme/tokens";

export interface ScriptIndicatorOptions {
  /** Unique indicator name to register (used in `chart.createIndicator(name)`). */
  name: string;
  /** Script source. */
  source: string;
  /** Language id (default 'superscript'). */
  language?: string;
  /**
   * 'price' puts the values on the price scale's precision (the default when
   * the script says `// @overlay`), 'volume' on the volume precision,
   * 'normal' uses `precision` (default 2).
   */
  series?: "price" | "volume" | "normal";
  /**
   * Decimals for a 'normal' script (default 2); raise it for small-valued
   * oscillators and ratios, which 2 decimals show as 0.00. 'price'/'volume'
   * scripts always follow the chart's precision.
   */
  precision?: number;
  /** Overrides the script's `// @overlay` directive. */
  overlay?: boolean;
  /**
   * Called when the script fails on the chart's data (klinecharts would keep
   * the previous values silently). The indicator then shows nothing until the
   * next successful calculation.
   */
  onError?: (error: unknown, diagnostics: Diagnostic[]) => void;
}

export type ScriptIndicatorErrorCode = "NAME_TAKEN" | "UNKNOWN_LANGUAGE";

/** Thrown when a script indicator cannot be registered under its name. */
export class ScriptIndicatorError extends Error {
  readonly code: ScriptIndicatorErrorCode;
  /** The indicator name. */
  readonly indicator: string;

  constructor(code: ScriptIndicatorErrorCode, indicator: string, message: string) {
    super(message);
    this.name = "ScriptIndicatorError";
    this.code = code;
    this.indicator = indicator;
  }
}

type Row = Record<string, number>;

/** A klinecharts indicator template built from a script, plus what the bridge knows about it. */
export type ScriptIndicatorTemplate = IndicatorTemplate<Row> & {
  name: string;
  shortName: string;
  calcParams: number[];
  figures: Array<IndicatorFigure<Row>>;
  /** The script's inputs, in calcParams order. */
  inputs: ScriptInput[];
};

/** Colours for plots that name none (a line needs a complete style, colour included). */
export const SCRIPT_PLOT_PALETTE: readonly string[] = [ACCENT, "#FF6D00", "#AB47BC", "#26A69A", "#EF5350", "#FFCA28"];

function legendTitle(title: string): string {
  return title === "" || /[:：]\s*$/.test(title) ? title : `${title}: `;
}

function width(n: number | undefined): number {
  return n !== undefined && Number.isFinite(n) && n > 0 ? n : 1;
}

/** A histogram bar's colour when the script gives none: the theme's up/down colour by side of the bar's base. */
function signColor(defaults: IndicatorStyle, value: number | undefined, base: number): string {
  const s = defaults.bars[0];
  return value === undefined ? s.noChangeColor : value >= base ? s.upColor : s.downColor;
}

/**
 * Compile a script and build the klinecharts indicator template for it,
 * without registering anything. Throws (SuperScriptError, or the language's
 * own error) for a script that does not compile.
 */
export function buildScriptIndicatorTemplate(options: ScriptIndicatorOptions): ScriptIndicatorTemplate {
  const languageId = options.language ?? "superscript";
  const lang = getLanguage(languageId);
  if (lang === undefined) {
    throw new ScriptIndicatorError("UNKNOWN_LANGUAGE", options.name, `unknown language: ${languageId}` +
      (languageId === "javascript" ? ' (register it first: registerLanguage(JavaScriptLanguage); it runs the source with new Function, immediately)' : ""));
  }
  const compiled = lang.compile(options.source);
  // A run with no data yields the plot metadata (ids/titles/styles), which the
  // script's plot() statements declare independently of the candles.
  const dry = compiled.run([]);
  const inputs = compiled.meta.inputs ?? dry.meta.inputs ?? [];
  const overlay = options.overlay ?? compiled.meta.overlay ?? dry.meta.overlay ?? false;
  const series = options.series ?? (overlay ? "price" : "normal");

  const lines: Array<Record<string, unknown>> = [];
  const figures: Array<IndicatorFigure<Row>> = dry.plots.map((p, i) => {
    const title = legendTitle(p.title);
    const color = p.style?.color;
    const key = p.id;
    if (p.style?.type === "histogram") {
      const base = p.style.histbase ?? 0;
      return {
        key,
        title,
        type: "bar",
        baseValue: base,
        styles: (data, _indicator, defaults) => ({ color: color ?? signColor(defaults, data.current.indicatorData?.[key], base) }),
      };
    }
    if (p.style?.type === "circle") {
      const c = color ?? SCRIPT_PLOT_PALETTE[i % SCRIPT_PLOT_PALETTE.length];
      return { key, title, type: "circle", styles: () => ({ color: c }) };
    }
    const dash = p.style?.lineStyle ?? (p.kind === "hline" ? "dashed" : "solid");
    lines.push({
      style: dash === "solid" ? "solid" : "dashed",
      smooth: false,
      size: width(p.style?.lineWidth),
      dashedValue: dash === "dotted" ? [1, 3] : dash === "dashed" ? [4, 4] : [2, 2],
      color: color ?? SCRIPT_PLOT_PALETTE[i % SCRIPT_PLOT_PALETTE.length],
    });
    return { key, title, type: "line" };
  });

  const isSuperScript = languageId === "superscript";
  const calc = (dataList: KLineData[], indicator?: { calcParams?: unknown[] }): Row[] => {
    try {
      // SuperScript never mutates its bars; other languages get copies.
      const bars: Bar[] = isSuperScript
        ? dataList
        : dataList.map((d) => ({ timestamp: d.timestamp, open: d.open, high: d.high, low: d.low, close: d.close, volume: d.volume }));
      const cp = indicator?.calcParams;
      const params: ScriptParams | undefined = inputs.length > 0 && Array.isArray(cp) ? (cp as Array<number | null>) : undefined;
      const res = compiled.run(bars, params);
      const rows: Row[] = dataList.map(() => ({}));
      for (const p of res.plots) {
        const values = p.values;
        for (let i = 0; i < rows.length; i++) {
          const v = values[i];
          // klinecharts treats a missing key as a gap; NaN/±Infinity would blank the axis.
          if (typeof v === "number" && Number.isFinite(v)) rows[i][p.id] = v;
        }
      }
      return rows;
    } catch (e) {
      const diagnostics = isSuperScriptError(e) ? e.diagnostics : [];
      if (options.onError !== undefined) options.onError(e, diagnostics);
      else console.warn(`[super-chart] script indicator "${options.name}" failed: ${String(e instanceof Error ? e.message : e)}`);
      // Nothing rather than the previous values, which klinecharts would keep.
      return dataList.map(() => ({}));
    }
  };

  const template: ScriptIndicatorTemplate = {
    name: options.name,
    shortName: dry.meta.title,
    series: series as IndicatorTemplate["series"],
    calcParams: inputs.map((i) => i.defval),
    figures,
    styles: (lines.length > 0 ? { lines } : {}) as IndicatorTemplate["styles"],
    calc,
    inputs,
  };
  // 'price'/'volume' take the chart's precision; klinecharts syncs it (9.8 at
  // creation, 9.7 on the next setPriceVolumePrecision), and would replace a
  // template precision anyway.
  if (series === "normal") template.precision = options.precision ?? 2;
  return template;
}

/** klinecharts' registry, as the bridge uses it (passed in, so this module runs in Node tests). */
export interface IndicatorRegistry {
  registerIndicator: (template: IndicatorTemplate<Row>) => void;
  getSupportedIndicators: () => string[];
}

export interface ScriptIndicatorBridge {
  register: (options: ScriptIndicatorOptions) => string;
  update: (chart: Chart | null, options: ScriptIndicatorOptions, paneId?: string) => string;
  schema: (name: string) => ScriptInput[] | undefined;
  setParams: (chart: Chart, name: string, params: ScriptParams, paneId?: string) => number[] | null;
}

/** What a bridge remembers: the names it registered (the only ones it may replace) and their inputs. */
export interface ScriptIndicatorBridgeState {
  owned: Set<string>;
  schemas: Map<string, ScriptInput[]>;
}

const STATE_KEY = Symbol.for("@zzyzxlabs/super-chart/script-indicators");

/**
 * The state for one klinecharts registry, keyed by its registerIndicator and
 * kept on globalThis, so every copy of this module on that registry shares it:
 * the ESM and CommonJS builds, or the package loaded twice by a bundler. Each
 * copy with its own state would refuse (NAME_TAKEN) the other's indicators.
 * Without a registry (plain Node with klinecharts' CommonJS entry, which has
 * none) the state is this copy's own, so importing still works.
 */
export function sharedBridgeState(registerIndicator: unknown): ScriptIndicatorBridgeState {
  if (typeof registerIndicator !== "function") return { owned: new Set(), schemas: new Map() };
  const g = globalThis as { [STATE_KEY]?: WeakMap<object, ScriptIndicatorBridgeState> };
  const byRegistry = g[STATE_KEY] ?? (g[STATE_KEY] = new WeakMap());
  let state = byRegistry.get(registerIndicator);
  if (state === undefined) {
    state = { owned: new Set(), schemas: new Map() };
    byRegistry.set(registerIndicator, state);
  }
  return state;
}

/** The bridge's registration logic over one klinecharts registry. */
export function createScriptIndicatorBridge(
  kc: IndicatorRegistry,
  state: ScriptIndicatorBridgeState = { owned: new Set(), schemas: new Map() },
): ScriptIndicatorBridge {
  const { owned, schemas } = state;

  const claim = (name: string): void => {
    if (!owned.has(name) && kc.getSupportedIndicators().includes(name)) {
      throw new ScriptIndicatorError("NAME_TAKEN", name,
        `an indicator named "${name}" already exists (a klinecharts built-in, or one the host or Super Chart registered); a script indicator cannot replace it. Choose another name.`);
    }
  };
  const register = (t: ScriptIndicatorTemplate): void => {
    // klinecharts copies what it knows from the template; `inputs` is ignored.
    kc.registerIndicator(t);
    owned.add(t.name);
    schemas.set(t.name, t.inputs);
  };
  const idsOf = (inputs: ScriptInput[] | undefined): string | undefined => inputs?.map((i) => i.id).join("\u0000");

  return {
    register (options) {
      claim(options.name);
      register(buildScriptIndicatorTemplate(options));
      return options.name;
    },

    update (chart, options, paneId) {
      claim(options.name);
      // Compile first: an invalid script throws before anything changes.
      const t = buildScriptIndicatorTemplate(options);
      const before = idsOf(schemas.get(options.name));
      register(t);
      if (chart !== null) {
        const sameInputs = before !== undefined && before === idsOf(t.inputs);
        chart.overrideIndicator({
          name: t.name,
          shortName: t.shortName,
          series: t.series,
          // No precision here: klinecharts would mark it as chosen by the host
          // and stop syncing a later 'price' series with the chart (below).
          figures: t.figures,
          // klinecharts merges styles: this is the whole lines array.
          styles: t.styles,
          calc: t.calc,
          ...(sameInputs ? {} : { calcParams: t.calcParams }),
        }, paneId);
        syncPrecision(chart, t, paneId);
      }
      return t.name;
    },

    schema (name) {
      const s = schemas.get(name);
      return s === undefined ? undefined : s.map((i) => ({ ...i }));
    },

    setParams (chart, name, params, paneId) {
      const schema = schemas.get(name);
      if (schema === undefined) return null;
      const current = currentParams(chart, name, paneId);
      const next = schema.map((input, i) => {
        const given = Array.isArray(params)
          ? (params as ReadonlyArray<number | null | undefined>)[i]
          : (params as Readonly<Record<string, number | null | undefined>>)[input.id];
        let v = typeof given === "number" && Number.isFinite(given) ? given : current?.[i] ?? input.defval;
        if (input.type === "int") v = Math.round(v);
        if (input.min !== undefined) v = Math.max(v, input.min);
        if (input.max !== undefined) v = Math.min(v, input.max);
        return v;
      });
      chart.overrideIndicator({ name, calcParams: next }, paneId);
      return next;
    },
  };
}

/** The instances of `name` on `paneId`, or on every pane. */
function instancesOf(chart: Chart, name: string, paneId?: string): unknown[] {
  if (paneId !== undefined) {
    const one = chart.getIndicatorByPaneId(paneId, name) as unknown;
    return one !== null && one !== undefined ? [one] : [];
  }
  const all = chart.getIndicatorByPaneId() as unknown;
  const out: unknown[] = [];
  if (all instanceof Map) {
    for (const pane of all.values()) {
      if (pane instanceof Map && pane.has(name)) out.push(pane.get(name));
    }
  }
  return out;
}

/**
 * Give a script's instances the precision of its (possibly new) series: the
 * chart's price/volume precision, or the template's for 'normal'. Through the
 * instance's setPrecision(p, true), which is how klinecharts 9 syncs series
 * precision itself: it does not mark the value as the host's choice, so a
 * later setPriceVolumePrecision (a symbol change) still reaches a 'price'
 * script, and a precision the host set explicitly is left alone.
 */
function syncPrecision(chart: Chart, t: ScriptIndicatorTemplate, paneId?: string): void {
  const chartPrecision = chart.getPriceVolumePrecision();
  const target = t.series === "price" ? chartPrecision.price : t.series === "volume" ? chartPrecision.volume : t.precision;
  if (target === undefined) return;
  for (const instance of instancesOf(chart, t.name, paneId)) {
    const set = (instance as { setPrecision?: unknown }).setPrecision;
    if (typeof set === "function") (set as (precision: number, flag?: boolean) => boolean).call(instance, target, true);
  }
}

/** The calcParams of `name` on `paneId`, or of its first instance on the chart. */
function currentParams(chart: Chart, name: string, paneId?: string): number[] | undefined {
  const cp = (instancesOf(chart, name, paneId)[0] as { calcParams?: unknown } | undefined)?.calcParams;
  return Array.isArray(cp) && cp.every((v) => typeof v === "number") ? (cp as number[]) : undefined;
}
